import React, { useState } from "react";

export function AccordionItem({ title = "How are assets installed?", children = "Assets are copied directly into your codebase." }: { title?: string; children?: React.ReactNode }) {
  const [open, setOpen] = useState(true);
  return (
    <div className="rounded-[8px] border border-border bg-card overflow-hidden">
      <button onClick={() => setOpen(!open)} className="w-full px-4 py-3 flex items-center justify-between text-xs font-semibold text-foreground">{title}</button>
      {open && <div className="px-4 pb-3 pt-1 text-xs text-muted-foreground border-t border-border/60">{children}</div>}
    </div>
  );
}
